{"command":"# Assuming the application server pod selector is 'app=server' and the required client's IP is '192.168.1.10'.
# We patch the existing default-deny-ingress policy to allow this specific source.

kubectl patch networkpolicy default-deny-ingress --type='merge' -p='[{"spec": {"ingress": [{"from": [{"ip": "192.168.1.10"}]}]}}]'"}

